E
cat > tests/CheckoutPricing.UnitTest/Features/Discount/DiscountAcceptanceTests.cs <<'E'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.Discount;

public class DiscountAcceptanceTests
{
    private static int Price(LoyaltyTier tier, int subtotalCents) =>
        new CalculateLoyaltyDiscount()
            .Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier))
            .TotalCents;

    [Fact]
    public void S1_BronzeCustomerIsChargedTheBronzePrice() // Bronze customer is charged the Bronze price
    {
        Assert.Equal(9500, Price(LoyaltyTier.Bronze, 10000));
    }

    [Fact]
    public void S2_SilverCustomerIsChargedTheSilverPrice() // Silver customer is charged the Silver price
    {
        Assert.Equal(9000, Price(LoyaltyTier.Silver, 10000));
    }

    [Fact]
    public void S3_GoldCustomerIsChargedTheGoldPrice() // Gold customer is charged the Gold price
    {
        Assert.Equal(8500, Price(LoyaltyTier.Gold, 10000));
    }

    [Fact]
    public void S4_BronzeTinyBasketKeepsReductionOnAWholeCentInCustomersFavour() // Bronze customer with a tiny basket keeps the reduction on a whole cent in their favour
    {
        Assert.Equal(7, Price(LoyaltyTier.Bronze, 7));
    }
}
E
cd tests/CheckoutPricing.UnitTest && dotnet test 2>&1 | grep -E "Failed|Passed|error|Assert|Expected|Actual|Total" | head -30

